import {
  CRAFTED_MONSTER_GEAR_SPECS,
  createMonsterEquipmentById,
  Item,
} from '../items';
import { Point } from '../types';

export const CRAFT_COMPLETION_INT_XP = 8;
export const CRAFT_COMPLETION_STR_XP = 6;

export interface RecipeIngredientRequirement {
  readonly itemTypeId: string;
  readonly materialName: string;
  readonly desiredCount: number;
}

export interface AppliedCraftMaterialEntry {
  readonly itemId: string;
  readonly itemTypeId: string;
  readonly itemName: string;
  readonly spriteKey: string;
}

export interface CraftingRecipe {
  readonly recipeId: string;
  readonly outputItemTypeId: string;
  readonly outputName: string;
  readonly ingredients: readonly RecipeIngredientRequirement[];
  readonly turnsRequired: number;
  readonly spCost: number;
  readonly createOutput: (options: { readonly id: string; readonly position: Point }) => Item;
}

export interface RecipeIngredientStatus {
  readonly itemTypeId: string;
  readonly materialName: string;
  readonly carriedCount: number;
  readonly appliedCount: number;
  readonly desiredCount: number;
  readonly missingToApply: number;
  readonly satisfiedForCraftMode: boolean;
  readonly hasEnoughCarried: boolean;
}

const craftingRecipes = new Map<string, CraftingRecipe>();

export function registerCraftingRecipe(recipe: CraftingRecipe): void {
  craftingRecipes.set(recipe.recipeId, recipe);
}

export function getAllCraftingRecipes(): CraftingRecipe[] {
  return Array.from(craftingRecipes.values());
}

export function getCraftingRecipeById(recipeId: string): CraftingRecipe | undefined {
  return craftingRecipes.get(recipeId);
}

export function isRegisteredCraftingMaterial(itemTypeId: string): boolean {
  for (const recipe of craftingRecipes.values()) {
    if (recipe.ingredients.some((ing) => ing.itemTypeId === itemTypeId)) {
      return true;
    }
  }
  return false;
}

export function countInventoryByItemTypeId(items: readonly Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.itemTypeId, (counts.get(item.itemTypeId) ?? 0) + item.amount);
  }
  return counts;
}

/**
 * Returns recipes where the actor currently carries AT LEAST 1 unit of at least one required ingredient.
 */
export function getContextualDiscoveredRecipes(inventoryItems: readonly Item[]): CraftingRecipe[] {
  const counts = countInventoryByItemTypeId(inventoryItems);
  return getAllCraftingRecipes().filter((recipe) =>
    recipe.ingredients.some((ing) => (counts.get(ing.itemTypeId) ?? 0) >= 1)
  );
}

/**
 * Computes carried, applied, desired, and missing counts for each ingredient of `recipe`.
 */
export function getRecipeIngredientStatuses(
  recipe: CraftingRecipe,
  inventoryItems: readonly Item[],
  appliedStack: readonly AppliedCraftMaterialEntry[] = []
): RecipeIngredientStatus[] {
  const carriedMap = countInventoryByItemTypeId(inventoryItems);
  const appliedMap = new Map<string, number>();
  for (const entry of appliedStack) {
    appliedMap.set(entry.itemTypeId, (appliedMap.get(entry.itemTypeId) ?? 0) + 1);
  }

  return recipe.ingredients.map((ing) => {
    const carriedCount = carriedMap.get(ing.itemTypeId) ?? 0;
    const appliedCount = appliedMap.get(ing.itemTypeId) ?? 0;
    const missingToApply = Math.max(0, ing.desiredCount - appliedCount);
    return {
      itemTypeId: ing.itemTypeId,
      materialName: ing.materialName,
      carriedCount,
      appliedCount,
      desiredCount: ing.desiredCount,
      missingToApply,
      satisfiedForCraftMode: appliedCount >= ing.desiredCount,
      hasEnoughCarried: carriedCount >= ing.desiredCount,
    };
  });
}

export function hasAllIngredientsCarried(
  recipe: CraftingRecipe,
  inventoryItems: readonly Item[]
): boolean {
  return getRecipeIngredientStatuses(recipe, inventoryItems).every((s) => s.hasEnoughCarried);
}

export function isRecipeFullySatisfiedByStack(
  recipe: CraftingRecipe,
  appliedStack: readonly AppliedCraftMaterialEntry[]
): boolean {
  const statuses = getRecipeIngredientStatuses(recipe, [], appliedStack);
  return (
    appliedStack.length > 0 &&
    statuses.every((s) => s.appliedCount === s.desiredCount) &&
    appliedStack.length === recipe.ingredients.reduce((acc, i) => acc + i.desiredCount, 0)
  );
}

// ============================================================================
// Register All 58 Monster-Derived Field Crafting Recipes
// ============================================================================

for (const spec of CRAFTED_MONSTER_GEAR_SPECS) {
  if (!spec.recipeIngredients || spec.recipeIngredients.length === 0) {
    continue;
  }
  registerCraftingRecipe({
    recipeId: spec.itemTypeId,
    outputItemTypeId: spec.itemTypeId,
    outputName: spec.name,
    ingredients: spec.recipeIngredients,
    turnsRequired: spec.turnsRequired ?? 6,
    spCost: spec.spCost ?? 20,
    createOutput: ({ id, position }) =>
      createMonsterEquipmentById(spec.itemTypeId, { id, position }),
  });
}
