export function getTutorialChapterMeta(id: TutorialChapterId): TutorialChapterMeta {
  const found = TUTORIAL_CHAPTERS.find((c) => c.id === id);
  if (!found) {
    return TUTORIAL_CHAPTERS[0];
  }
  return found;
}

export function getNextTutorialChapterId(id: TutorialChapterId): TutorialChapterId | null {
  const idx = TUTORIAL_CHAPTER_ORDER.indexOf(id);
  if (idx === -1 || idx + 1 >= TUTORIAL_CHAPTER_ORDER.length) {
    return null;
  }
  return TUTORIAL_CHAPTER_ORDER[idx + 1];
}

// ============================================================================
// Tutorial Completion Persistence (`biohoward.tutorial.v1`)
// ============================================================================

export const TUTORIAL_STORAGE_KEY = 'biohoward.tutorial.v1';

export interface TutorialProgressStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export class InMemoryTutorialProgressStorage implements TutorialProgressStorage {
  private readonly map = new Map<string, string>();

  public getItem(key: string): string | null {
    return this.map.get(key) ?? null;
  }

  public setItem(key: string, value: string): void {
    this.map.set(key, value);
  }
}

export class BrowserLocalTutorialProgressStorage implements TutorialProgressStorage {
  public getItem(key: string): string | null {
    try {
      if (typeof localStorage !== 'undefined') {
        return localStorage.getItem(key);
      }
    } catch {
      // Ignore storage access errors in restricted environments
    }
    return null;
  }

  public setItem(key: string, value: string): void {
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(key, value);
      }
    } catch {
      // Ignore storage quota / privacy errors
    }
  }
}

export class TutorialProgressManager {
  private readonly storage: TutorialProgressStorage;
  private readonly storageKey: string;

  constructor(
    storage: TutorialProgressStorage = new BrowserLocalTutorialProgressStorage(),
    storageKey: string = TUTORIAL_STORAGE_KEY
  ) {
    this.storage = storage;
    this.storageKey = storageKey;
  }

  public getCompletedChapterIds(): TutorialChapterId[] {
    const raw = this.storage.getItem(this.storageKey);
    if (!raw) {
      return [];
    }
    try {
      const parsed = JSON.parse(raw) as { completedChapterIds?: unknown };
      if (!Array.isArray(parsed?.completedChapterIds)) {
        return [];
      }
      const validSet = new Set<string>(TUTORIAL_CHAPTER_ORDER);
      const unique: TutorialChapterId[] = [];
      for (const id of parsed.completedChapterIds) {
        if (
          typeof id === 'string' &&
          validSet.has(id) &&
          !unique.includes(id as TutorialChapterId)
        ) {
          unique.push(id as TutorialChapterId);
        }
      }
      return unique;
    } catch {
      return [];
    }
  }

  public isCompleted(chapterId: TutorialChapterId): boolean {
    return this.getCompletedChapterIds().includes(chapterId);
  }

  public markCompleted(chapterId: TutorialChapterId): void {
    const current = this.getCompletedChapterIds();
    if (!current.includes(chapterId)) {
      current.push(chapterId);
      this.storage.setItem(
        this.storageKey,
        JSON.stringify({ version: 1, completedChapterIds: current })
      );
    }
  }
}

// ============================================================================
// Dialog Choice IDs & End-of-Chapter Dialog Builder
// ============================================================================

export const TUTORIAL_CHOICE_NEXT_CHAPTER = 'tutorial_next_chapter';
export const TUTORIAL_CHOICE_CHAPTER_SELECT = 'tutorial_chapter_select';
export const TUTORIAL_CHOICE_RETURN_TITLE = 'tutorial_return_title';

function buildChapterCompletionChoices(chapterId: TutorialChapterId): DialogChoice[] {
  const nextId = getNextTutorialChapterId(chapterId);
  const choices: DialogChoice[] = [];
  if (nextId) {
    const nextMeta = getTutorialChapterMeta(nextId);
    choices.push({
      choiceId: TUTORIAL_CHOICE_NEXT_CHAPTER,
      labelEn: `Next: Ch. ${nextMeta.chapterNumber} ▸`,
      labelZh: `下一章：第 ${nextMeta.chapterNumber} 章 ▸`,
      variant: 'primary',
    });
  }
  choices.push({
    choiceId: TUTORIAL_CHOICE_CHAPTER_SELECT,
    labelEn: 'Chapter Select',
    labelZh: '返回章節選單',
    variant: nextId ? 'secondary' : 'primary',
  });
  choices.push({
    choiceId: TUTORIAL_CHOICE_RETURN_TITLE,
    labelEn: 'Return to Title',
    labelZh: '返回標題畫面',
    variant: 'secondary',
  });
  return choices;
}

function buildChapterCompletionDialog(
  chapterId: TutorialChapterId,
  portraitSpriteKey: string,
  speakerEn: string,
  speakerZh: string,
  summaryEn: string,
  summaryZh: string
): DialogSequence {
  const hReminderEn =
    '\n\nTip: Anytime during the game, [Right-Click] (or press [Esc]) to call out the Action Menu of commands, or press [h] to check all controls and shortcuts!';
  const hReminderZh =
    '\n\n提示：在遊戲中隨時按【滑鼠右鍵】（或【Esc】）即可叫出包含各項指令的行動選單，或按【h】鍵查看所有操作指令與完整快捷鍵清單！';

  return {
    id: `tutorial_${chapterId}_complete`,
    pages: [
      {
        portraitSpriteKey,
        speakerEn,
        speakerZh,
        bodyEn: `${summaryEn}${hReminderEn}`,
        bodyZh: `${summaryZh}${hReminderZh}`,
      },
    ],
    choices: buildChapterCompletionChoices(chapterId),
  };
}

