function clearWorldEntitiesAndItems(world: GameWorld): void {
  for (const enemy of [...world.enemies]) {
    world.removeEnemy(enemy.id);
  }
  world.items.length = 0;
  world.traps.length = 0;
}

function resetPlayerCleanState(world: GameWorld, pos: Point): void {
  const p = world.player;
  p.setInPit(false);
  p.setBlindTurns(0);
  p.setParalysisTurns(0);
  p.setSleepTurns(0);
  p.setFaintTurns(0);
  p.setBleedingTurns(0);
  p.setArmorBreakTurns(0);
  p.setSpeedUpTurns(0);
  p.setInvisibleTurns(0);
  p.setSeeInvisibleTurns(0);
  p.setCleverTurns(0);
  p.setShieldTurns(0);
  p.setScudTurns(0);
  p.setRoarTurns(0);
  p.setToughTurns(0);

  for (const slot of [
    'head',
    'body',
    'arms',
    'weapon',
    'shield',
    'feet',
    'amulet',
    'ring1',
    'ring2',
  ] as const) {
    p.destroyEquippedSlot(slot);
  }
  p.inventory.clear();
  p.setSatietySilent(900);
  p.position = { ...pos };
  p.stats.hp = p.stats.maxHp;
  p.stats.mp = p.stats.maxMp;
  p.stats.sp = p.stats.maxSp;
  p.preventDeath = true;
  p.pauseSatietyDrain = true;

  world.tutorialUsedStairsDown = false;
  world.tutorialEnteredPortal = false;
  world.tutorialPerformedDash = false;
  world.tutorialThrownHitEnemy = false;
  world.tutorialFoundTrapBySearch = false;
}

function makeStationaryEnemy<T extends Enemy>(enemy: T): T {
  enemy.aiController = {
    decideNextAction: () => new WaitAction(),
  };
  return enemy;
}

function makeTrainingBoar(id: string, position: Point): Boar {
  const boar = makeStationaryEnemy(new Boar({ id, position }));
  boar.stats.maxHp = 300;
  boar.stats.hp = 300;
  boar.preventDeath = true;
  return boar;
}

function countOwnedItemByType(world: GameWorld, itemTypeId: string): number {
  let count = 0;
  for (const item of world.player.inventory.getItems()) {
    if (item.itemTypeId === itemTypeId) {
      count += item.amount;
    }
  }
  const loadout = world.player.getEquipmentLoadout();
  for (const eq of Object.values(loadout)) {
    if (eq && eq.itemTypeId === itemTypeId) {
      count += eq.amount;
    }
  }
  return count;
}

function hasAnyBoundHotkey(world: GameWorld): boolean {
  for (const slot of ['1', '2', '3', '4', '5', '6', '7', '8', '9', '0'] as const) {
    if (world.player.getSkillHotkey(slot) !== null) {
      return true;
    }
  }
  return false;
}

