/**
 * General-purpose, pure-TypeScript Pop-Up Dialog Queue (`src/core/dialog/index.ts`).
 *
 * Zero DOM dependencies — usable for both interactive Tutorial guidance and future
 * in-game Story cutscenes, Boss encounters, lore shrines, and epilogues via `GameWorld`.
 */

export interface DialogChoice {
  readonly choiceId: string;
  readonly labelEn: string;
  readonly labelZh: string;
  readonly variant?: 'primary' | 'secondary';
}

export interface DialogPage {
  readonly portraitSpriteKey?: string;
  readonly speakerEn: string;
  readonly speakerZh: string;
  readonly bodyEn: string;
  readonly bodyZh: string;
  readonly confirmLabelEn?: string;
  readonly confirmLabelZh?: string;
}

export interface DialogSequence {
  readonly id: string;
  readonly pages: readonly DialogPage[];
  readonly choices?: readonly DialogChoice[];
}

export interface ActiveDialogState {
  readonly sequence: DialogSequence;
  readonly pageIndex: number;
  readonly totalPages: number;
  readonly currentPage: DialogPage;
  readonly isLastPage: boolean;
  readonly hasChoices: boolean;
  readonly choices: readonly DialogChoice[];
  readonly selectedChoiceIndex: number;
}

export interface DialogAdvanceResult {
  readonly action: 'next_page' | 'closed' | 'choice_selected' | 'noop';
  readonly sequenceId?: string;
  readonly choiceId?: string;
}

export type DialogResolutionListener = (result: DialogAdvanceResult) => void;

export class DialogQueue {
  private readonly queue: DialogSequence[] = [];
  private pageIndex = 0;
  private selectedChoiceIndex = 0;
  private readonly listeners = new Set<DialogResolutionListener>();

  public subscribe(listener: DialogResolutionListener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private emit(result: DialogAdvanceResult): DialogAdvanceResult {
    if (result.action !== 'noop') {
      for (const listener of this.listeners) {
        listener(result);
      }
    }
    return result;
  }

  public enqueue(sequence: DialogSequence, options?: { replaceActive?: boolean }): void {
    if (!sequence || sequence.pages.length === 0) {
      return;
    }
    if (options?.replaceActive) {
      this.queue.length = 0;
      this.pageIndex = 0;
      this.selectedChoiceIndex = 0;
    }
    const wasEmpty = this.queue.length === 0;
    this.queue.push(sequence);
    if (wasEmpty) {
      this.pageIndex = 0;
      this.selectedChoiceIndex = 0;
    }
  }

  public hasActive(): boolean {
    return this.queue.length > 0;
  }

  public getActive(): ActiveDialogState | null {
    if (this.queue.length === 0) {
      return null;
    }
    const sequence = this.queue[0];
    const totalPages = sequence.pages.length;
    const clampedPage = Math.max(0, Math.min(totalPages - 1, this.pageIndex));
    const isLastPage = clampedPage === totalPages - 1;
    const choices = isLastPage && sequence.choices ? sequence.choices : [];
    const hasChoices = choices.length > 0;
    const clampedChoice = hasChoices
      ? Math.max(0, Math.min(choices.length - 1, this.selectedChoiceIndex))
      : 0;

    return {
      sequence,
      pageIndex: clampedPage,
      totalPages,
      currentPage: sequence.pages[clampedPage],
      isLastPage,
      hasChoices,
      choices,
      selectedChoiceIndex: clampedChoice,
    };
  }

  public moveChoiceSelection(delta: number): void {
    const active = this.getActive();
    if (!active || !active.hasChoices) {
      return;
    }
    const len = active.choices.length;
    this.selectedChoiceIndex = (((active.selectedChoiceIndex + delta) % len) + len) % len;
  }

  public setChoiceSelection(index: number): void {
    const active = this.getActive();
    if (!active || !active.hasChoices) {
      return;
    }
    this.selectedChoiceIndex = Math.max(0, Math.min(active.choices.length - 1, index));
  }

  /**
   * Advances to the next page (`0` ticks), closes the dialog on the final page when there are no choices,
   * or confirms the highlighted choice when `hasChoices` is true on the final page.
   */
  public advance(): DialogAdvanceResult {
    const active = this.getActive();
    if (!active) {
      return { action: 'noop' };
    }
    const sequenceId = active.sequence.id;
    if (!active.isLastPage) {
      this.pageIndex = active.pageIndex + 1;
      this.selectedChoiceIndex = 0;
      return this.emit({ action: 'next_page', sequenceId });
    }

    if (active.hasChoices) {
      const chosen = active.choices[active.selectedChoiceIndex] ?? active.choices[0];
      this.shiftQueue();
      return this.emit({
        action: 'choice_selected',
        sequenceId,
        choiceId: chosen.choiceId,
      });
    }

    this.shiftQueue();
    return this.emit({ action: 'closed', sequenceId });
  }

  /**
   * Directly confirms a choice by `choiceId` on the active dialog's final page (used by mouse click handlers).
   */
  public confirmChoiceById(choiceId: string): DialogAdvanceResult {
    const active = this.getActive();
    if (!active || !active.hasChoices) {
      return { action: 'noop' };
    }
    const match = active.choices.find((c) => c.choiceId === choiceId);
    if (!match) {
      return { action: 'noop' };
    }
    const sequenceId = active.sequence.id;
    this.shiftQueue();
    return this.emit({
      action: 'choice_selected',
      sequenceId,
      choiceId: match.choiceId,
    });
  }

  /**
   * Dismisses a standard guidance/story dialog on `Escape` / Right-Click (`0` ticks).
   * If the active page presents mandatory branching choices, keeps it open unless a fallback choice is provided.
   */
  public dismissActive(fallbackChoiceId?: string): DialogAdvanceResult {
    const active = this.getActive();
    if (!active) {
      return { action: 'noop' };
    }
    if (active.hasChoices) {
      if (fallbackChoiceId) {
        return this.confirmChoiceById(fallbackChoiceId);
      }
      return { action: 'noop' };
    }
    const sequenceId = active.sequence.id;
    this.shiftQueue();
    return this.emit({ action: 'closed', sequenceId });
  }

  public clear(): void {
    this.queue.length = 0;
    this.pageIndex = 0;
    this.selectedChoiceIndex = 0;
  }

  private shiftQueue(): void {
    this.queue.shift();
    this.pageIndex = 0;
    this.selectedChoiceIndex = 0;
  }
}
