import { buildEnemyRawMaterialDrops } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface LionOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Lion (`雄獅`):
 * - Fast `Lv. 7` apex savannah predator (`Walking`, `sensingRange = 8`, `canOpenDoors = false`).
 * - Combat AI: `40%` `Roar` (`戰吼`, `30 SP`, `+10` full turns of `+50% STR` min `+3` when `!hasRoar()`),
 *   `40%` `Bite` (`噬咬`, `10 SP`, `40%` `Bleeding` `5–8t`), `20%` `Melee` / `A*` Advance.
 * - Drops `Meat of Lion` (`雄獅肉`, `10%`, `+300` Satiety, `3.5 wt`) and `Roar` (`戰吼`) Soul (`5%`), with no crafting trophy drops.
 */
export class Lion extends Enemy {
  constructor(options: LionOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_lion',
      name: 'Lion',
      position: options.position,
      spriteKey: 'enemy_lion',
      level: 7,
      xpReward: 250,
      movementType: 'walking',
      sensingRange: 8,
      canOpenDoors: false,
      scoreValue: 575,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 300,
      meatWeight: 3.5,
      soulDropId: 'roar',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      warSkills: [
        { skillId: 'roar', chance: 0.4, level: 5 },
        { skillId: 'bite', chance: 0.4, level: 5 },
      ],
      trophyDrops: buildEnemyRawMaterialDrops('enemy_lion'),
      attributes: {
        str: 20,
        con: 15,
        int: 4,
        wis: 6,
        agi: 17,
        luk: 10,
      },
    });
  }
}
