import { buildEnemyRawMaterialDrops } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface BearOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Bear (`巨熊`):
 * - Towering `Lv. 6` dungeon bruiser (`Walking`, `sensingRange = 7`, `canOpenDoors = false`).
 * - Combat AI: `40%` `Bash` (`猛擊`, `10 SP`, `30%` non-stacking `Faint` for `2–4` turns), `60%` `Melee`.
 * - Drops `Meat of Bear` (`巨熊肉`, `10%`, `+280` Satiety, `3.5 wt`) and `Bash` (`猛擊`) Soul (`5%`), with no crafting trophy drops.
 */
export class Bear extends Enemy {
  constructor(options: BearOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_bear',
      name: 'Bear',
      position: options.position,
      spriteKey: 'enemy_bear',
      level: 6,
      xpReward: 185,
      movementType: 'walking',
      sensingRange: 7,
      canOpenDoors: false,
      scoreValue: 425,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 280,
      meatWeight: 3.5,
      soulDropId: 'bash',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      warSkills: [{ skillId: 'bash', chance: 0.4, level: 4 }],
      trophyDrops: buildEnemyRawMaterialDrops('enemy_bear'),
      attributes: {
        str: 18,
        con: 16,
        int: 3,
        wis: 5,
        agi: 9,
        luk: 8,
      },
    });
  }
}
