import { SeededRNG } from '../SeededRNG';

export interface ScrollRuneEntry {
  readonly runeId: string;
  readonly runeWords: string;
}

/**
 * Curated pool of mysterious arcane Latin rune strings inscribed on unidentified scrolls.
 * If the number of registered scroll types ever exceeds this list, `getScrollRunePool`
 * deterministically synthesizes additional unique arcane rune labels.
 */
export const CURATED_SCROLL_RUNES: readonly ScrollRuneEntry[] = [
  { runeId: 'zelgo_mer', runeWords: 'ZELGO MER' },
  { runeId: 'nr_9', runeWords: 'NR 9' },
  { runeId: 'juyed_awk', runeWords: 'JUYED AWK' },
  { runeId: 'venzar_borgavve', runeWords: 'VENZAR BORGAVVE' },
  { runeId: 'elam_ebow', runeWords: 'ELAM EBOW' },
  { runeId: 'velox_neb', runeWords: 'VELOX NEB' },
  { runeId: 'garven_deh', runeWords: 'GARVEN DEH' },
  { runeId: 'temov', runeWords: 'TEMOV' },
  { runeId: 'pratyavayah', runeWords: 'PRATYAVAYAH' },
  { runeId: 'foobie_bletch', runeWords: 'FOOBIE BLETCH' },
  { runeId: 'andova_begarin', runeWords: 'ANDOVA BEGARIN' },
  { runeId: 'tharr', runeWords: 'THARR' },
];

const ARCANE_SYLLABLES_FIRST = [
  'AEL',
  'KHOR',
  'THAL',
  'VEX',
  'MYR',
  'ZOR',
  'NYX',
  'SOL',
] as const;

const ARCANE_SYLLABLES_SECOND = [
  'VYR',
  'ZUN',
  'OMN',
  'KAI',
  'DRA',
  'LOK',
  'PHA',
  'TOR',
] as const;

/**
 * Synthesizes a deterministic extra arcane rune string whenever registered scroll types
 * exceed `CURATED_SCROLL_RUNES.length`.
 */
export function synthesizeExtraScrollRune(extraIndex: number): ScrollRuneEntry {
  const n = Math.max(1, Math.floor(extraIndex));
  const idx = n - 1;
  const first = ARCANE_SYLLABLES_FIRST[idx % ARCANE_SYLLABLES_FIRST.length];
  const second =
    ARCANE_SYLLABLES_SECOND[
      Math.floor(idx / ARCANE_SYLLABLES_FIRST.length) % ARCANE_SYLLABLES_SECOND.length
    ];
  const cycle = Math.floor(
    idx / (ARCANE_SYLLABLES_FIRST.length * ARCANE_SYLLABLES_SECOND.length)
  );
  const suffix = cycle > 0 ? ` ${cycle + 1}` : '';
  return {
    runeId: `rune_extra_${n}`,
    runeWords: `${first} ${second}${suffix}`,
  };
}

export function getScrollRunePool(requiredCount: number): ScrollRuneEntry[] {
  const pool: ScrollRuneEntry[] = [...CURATED_SCROLL_RUNES];
  let extraIdx = 1;
  while (pool.length < requiredCount) {
    pool.push(synthesizeExtraScrollRune(extraIdx++));
  }
  return pool;
}

export function getScrollRuneById(runeId: string): ScrollRuneEntry {
  const curated = CURATED_SCROLL_RUNES.find((r) => r.runeId === runeId);
  if (curated) {
    return curated;
  }
  const extraMatch = /^rune_extra_(\d+)$/.exec(runeId);
  if (extraMatch) {
    return synthesizeExtraScrollRune(Number(extraMatch[1]));
  }
  // Also accept direct raw runeWords if passed directly
  const byWords = CURATED_SCROLL_RUNES.find((r) => r.runeWords === runeId);
  if (byWords) {
    return byWords;
  }
  return CURATED_SCROLL_RUNES[0];
}

export function formatUnidentifiedScrollName(
  runeWords: string,
  lang: 'en' | 'zh-TW'
): string {
  return lang === 'zh-TW' ? `卷軸「${runeWords}」` : `Scroll "${runeWords}"`;
}

const registeredScrollTypeIds = new Set<string>();

/**
 * Registers a scroll `itemTypeId` so every new game automatically pairs it with a unique random rune label.
 */
export function registerScrollType(itemTypeId: string): void {
  registeredScrollTypeIds.add(itemTypeId);
}

export function getRegisteredScrollTypeIds(): string[] {
  return Array.from(registeredScrollTypeIds);
}

/**
 * Generates a fresh randomized 1-to-1 mapping from every registered scroll `itemTypeId`
 * (plus any additional `extraScrollTypeIds`) to a unique `runeId` using `rng`.
 */
export function createRandomizedScrollLabelMap(
  rng: SeededRNG,
  extraScrollTypeIds: readonly string[] = []
): Record<string, string> {
  const allTypeIds = Array.from(
    new Set([...getRegisteredScrollTypeIds(), ...extraScrollTypeIds])
  ).sort();
  const pool = getScrollRunePool(Math.max(CURATED_SCROLL_RUNES.length, allTypeIds.length));
  const shuffledRunes = rng.shuffle(pool);
  const mapping: Record<string, string> = {};
  for (let i = 0; i < allTypeIds.length; i++) {
    mapping[allTypeIds[i]] = shuffledRunes[i].runeId;
  }
  return mapping;
}
