/**
 * Pure-TypeScript Difficulty System (`src/core/difficulty/index.ts`).
 *
 * Centralizes all balance multipliers, floor generation parameters, starter kit flags,
 * and score multipliers for `Easy` (`'easy'`), `Normal` (`'normal'`, 1.0x baseline), and `Hard` (`'hard'`).
 */

export type DifficultyId = 'easy' | 'normal' | 'hard';

export const DIFFICULTY_ORDER: readonly DifficultyId[] = ['easy', 'normal', 'hard'];

export const DEFAULT_DIFFICULTY: DifficultyId = 'normal';

export interface DifficultyTierWeights {
  readonly atOrBelow: number;
  readonly plusOne: number;
  readonly plusTwo: number;
}

export interface DifficultyConfig {
  readonly id: DifficultyId;
  readonly spriteKey: string;
  readonly xpMultiplier: number;
  readonly initialSatiety: number;
  readonly satietyDrainMultiplier: number;
  readonly enemyDamageMultiplier: number;
  readonly enemyMaxHpMultiplier: number;
  readonly floorRoomItemCount: number;
  readonly lootDropMultiplier: number;
  readonly soulDropMultiplier: number;
  readonly enemySpawnScale: number;
  readonly tierWeights: DifficultyTierWeights;
  readonly trapCountMultiplier: number;
  readonly scoreMultiplier: number;
  readonly grantsStarterKit: boolean;
}

