export function normalizeDifficultyId(value: unknown): DifficultyId {
  if (value === 'easy' || value === 'normal' || value === 'hard') {
    return value;
  }
  return DEFAULT_DIFFICULTY;
}

export function getDifficultyConfig(difficulty: DifficultyId = DEFAULT_DIFFICULTY): DifficultyConfig {
  return DIFFICULTY_CONFIGS[difficulty] ?? DIFFICULTY_CONFIGS.normal;
}
