import { DoorState, MovementType, TileType, VisibilityState } from './types';

/**
 * Represents a single cell on the 2D dungeon map.
 * Encapsulates passability, line-of-sight transparency, door state, and Fog of War visibility.
 */
export class Tile {
  public type: TileType;
  public doorState: DoorState;
  public visibility: VisibilityState;
  public lastSeenDoorState: DoorState;

  constructor(
    type: TileType,
    doorState: DoorState = type === TileType.DOOR ? DoorState.CLOSED : DoorState.NONE,
    visibility: VisibilityState = VisibilityState.UNEXPLORED
  ) {
    this.type = type;
    this.doorState = type === TileType.DOOR ? doorState : DoorState.NONE;
    this.visibility = visibility;
    this.lastSeenDoorState = this.doorState;
  }

  public static createFloor(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.FLOOR, DoorState.NONE, visibility);
  }

  public static createWall(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.WALL, DoorState.NONE, visibility);
  }

  public static createDoor(
    state: DoorState.CLOSED | DoorState.OPEN = DoorState.CLOSED,
    visibility: VisibilityState = VisibilityState.UNEXPLORED
  ): Tile {
    return new Tile(TileType.DOOR, state, visibility);
  }

  public static createStairsUp(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.STAIRS_UP, DoorState.NONE, visibility);
  }

  public static createStairsDown(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.STAIRS_DOWN, DoorState.NONE, visibility);
  }

  public static createPortal(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.PORTAL, DoorState.NONE, visibility);
  }

  public static createWater(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.WATER, DoorState.NONE, visibility);
  }

  /**
   * Whether a standard land/aerial actor (`walking` or `flying`) can step onto this tile.
   * Floor, Water, Stairs, and Portal are passable; Wall is non-passable; Door is passable only when OPEN.
   */
  public isPassable(): boolean {
    switch (this.type) {
      case TileType.FLOOR:
      case TileType.WATER:
      case TileType.STAIRS_UP:
      case TileType.STAIRS_DOWN:
      case TileType.PORTAL:
        return true;
      case TileType.WALL:
        return false;
      case TileType.DOOR:
        return this.doorState === DoorState.OPEN;
    }
  }

  /**
   * Whether an actor with `movementType` (`'walking' | 'flying' | 'swimming'`) can occupy/step onto this tile:
   * - `'swimming'`: strictly `TileType.WATER` only.
   * - `'walking'` / `'flying'`: any `isPassable()` tile (`FLOOR`, `WATER`, `OPEN` `DOOR`, `STAIRS`, `PORTAL`).
   */
  public canBeTraversedBy(movementType: MovementType): boolean {
    if (movementType === 'swimming') {
      return this.type === TileType.WATER;
    }
    return this.isPassable();
  }

  /**
   * Whether light / sight / projectiles can pass through this tile.
   * Floor, Water, Stairs, and Portal are transparent; Wall and CLOSED Door block sight; OPEN Door is transparent.
   */
  public isTransparent(): boolean {
    switch (this.type) {
      case TileType.FLOOR:
      case TileType.WATER:
      case TileType.STAIRS_UP:
      case TileType.STAIRS_DOWN:
      case TileType.PORTAL:
        return true;
      case TileType.WALL:
        return false;
      case TileType.DOOR:
        return this.doorState === DoorState.OPEN;
    }
  }

  public isWater(): boolean {
    return this.type === TileType.WATER;
  }

  public isStairsUp(): boolean {
    return this.type === TileType.STAIRS_UP;
  }

  public isStairsDown(): boolean {
    return this.type === TileType.STAIRS_DOWN;
  }

  public isPortal(): boolean {
    return this.type === TileType.PORTAL;
  }

  public isDoor(): boolean {
    return this.type === TileType.DOOR;
  }

  public isClosedDoor(): boolean {
    return this.type === TileType.DOOR && this.doorState === DoorState.CLOSED;
  }

  public isOpenDoor(): boolean {
    return this.type === TileType.DOOR && this.doorState === DoorState.OPEN;
  }

  /**
   * Opens a closed door. Returns true if the state changed.
   */
  public openDoor(): boolean {
    if (this.type !== TileType.DOOR || this.doorState !== DoorState.CLOSED) {
      return false;
    }
    this.doorState = DoorState.OPEN;
    if (this.visibility === VisibilityState.VISIBLE) {
      this.lastSeenDoorState = DoorState.OPEN;
    }
    return true;
  }

  /**
   * Closes an open door. Returns true if the state changed.
   */
  public closeDoor(): boolean {
    if (this.type !== TileType.DOOR || this.doorState !== DoorState.OPEN) {
      return false;
    }
    this.doorState = DoorState.CLOSED;
    if (this.visibility === VisibilityState.VISIBLE) {
      this.lastSeenDoorState = DoorState.CLOSED;
    }
    return true;
  }

  /**
   * Updates tile visibility state and records lastSeenDoorState when currently visible.
   */
  public setVisibility(visibility: VisibilityState): void {
    this.visibility = visibility;
    if (visibility === VisibilityState.VISIBLE) {
      this.lastSeenDoorState = this.doorState;
    }
  }
}
