import { Actor } from '../entities/Actor';
import { SeededRNG } from '../SeededRNG';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export const DEFAULT_BLINDNESS_MIN_TURNS = 10;
export const DEFAULT_BLINDNESS_MAX_TURNS = 20;

export interface BlindnessPotionOptions extends PotionItemOptions {
  readonly minTurns?: number;
  readonly maxTurns?: number;
}

/**
 * Potion of Blindness (`失明藥水`): inflicts 10–20 turns of additive Blind (`失明`) on its target
 * when quaffed (+10 Satiety) or thrown (-50% accuracy & evasion, deprives vision & sight identification).
 */
export class BlindnessPotion extends PotionItem {
  public readonly minTurns: number;
  public readonly maxTurns: number;

  constructor(options: BlindnessPotionOptions) {
    const minTurns = Math.max(1, Math.round(options.minTurns ?? DEFAULT_BLINDNESS_MIN_TURNS));
    const maxTurns = Math.max(
      minTurns,
      Math.round(options.maxTurns ?? DEFAULT_BLINDNESS_MAX_TURNS)
    );
    super({
      id: options.id ?? `blindness-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Blindness',
      itemTypeId: 'blindness_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `A blinding concoction that steals its target's sight for ${minTurns}–${maxTurns} turns when quaffed or thrown.`,
    });
    this.minTurns = minTurns;
    this.maxTurns = maxTurns;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW'
      ? `失明 ${this.minTurns}–${this.maxTurns}回合`
      : `Blind ${this.minTurns}–${this.maxTurns}t`;
  }

  public applyToTarget(target: Actor, rng?: SeededRNG): number {
    if (!target.isAlive()) {
      return 0;
    }
    const prevTurns = target.blindTurns;
    const rolledTurns = rng
      ? rng.nextInt(this.minTurns, this.maxTurns)
      : Math.floor(Math.random() * (this.maxTurns - this.minTurns + 1)) + this.minTurns;
    const nextTurns = target.addBlindTurns(rolledTurns);
    return nextTurns > prevTurns ? nextTurns : 0;
  }

  public override applyQuaffEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult {
    const added = this.applyToTarget(target, rng);
    return {
      kind: 'blind',
      observableEffect: added > 0,
      blindTurnsAdded: added,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): BlindnessPotion {
    const cloned = new BlindnessPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
    };
  }
}

registerPotionType('blindness_potion');
