import { buildEnemyRawMaterialDrops } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface WolfOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Wolf (`野狼`):
 * - Swift `Lv. 5` apex pack hunter (`Walking`, `sensingRange = 8`, `canOpenDoors = false`).
 * - Combat AI: `40%` `Bite` (`噬咬`, `10 SP`), `40%` `Scud` (`迅敏`, `10 MP` `+50%` `AGI` buff for `10` turns when not already active), `20%` `Melee`.
 * - Drops `Meat of Wolf` (`野狼肉`, `10%`, `+240` Satiety, `2.5 wt`) and `Scud` (`迅敏`) Soul (`5%`), with no crafting trophy drops.
 */
export class Wolf extends Enemy {
  constructor(options: WolfOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_wolf',
      name: 'Wolf',
      position: options.position,
      spriteKey: 'enemy_wolf',
      level: 5,
      xpReward: 130,
      movementType: 'walking',
      sensingRange: 8,
      canOpenDoors: false,
      scoreValue: 300,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 240,
      meatWeight: 2.5,
      soulDropId: 'scud',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      warSkills: [{ skillId: 'bite', chance: 0.4, level: 3 }],
      magicSkills: [{ skillId: 'scud', chance: 0.4, level: 3 }],
      trophyDrops: buildEnemyRawMaterialDrops('enemy_wolf'),
      attributes: {
        str: 15,
        con: 11,
        int: 4,
        wis: 6,
        agi: 18,
        luk: 10,
      },
    });
  }
}
