import { rollWeaponDice, WeaponDice } from '../items/EquipmentItem';
import type { SeededRNG } from '../SeededRNG';

export const MIN_SKILL_LEVEL = 1;
export const MAX_SKILL_LEVEL = 10;

export interface SerializedSkillProgress {
  readonly level: number;
  readonly xp: number;
}

export interface SkillLevelUpEvent {
  readonly skillId: string;
  readonly oldLevel: number;
  readonly newLevel: number;
}

export const SKILL_EXERCISE_XP = {
  warHit: 10,
  magicHit: 12,
  magicExtraPierceHit: 4,
  selfBuffCombat: 6,
  fledglingKill: 8,
  scavengerRottenEat: 60,
  duplicateSoulResonance: 40,
} as const;

export function clampSkillLevel(level?: number): number {
  if (typeof level !== 'number' || !Number.isFinite(level)) {
    return MIN_SKILL_LEVEL;
  }
  return Math.max(MIN_SKILL_LEVEL, Math.min(MAX_SKILL_LEVEL, Math.floor(level)));
}

/**
 * Computes the Skill XP required to advance from `level` (`1..9`) to `level + 1`:
 * `15 + 25 * level` (`40, 65, 90, 115, 140, 165, 190, 215, 240`; `1,260` cumulative XP; `0` at `Lv. 10 MAX`).
 */
export function computeSkillXpToNextLevel(level: number): number {
  const safeLevel = clampSkillLevel(level);
  if (safeLevel >= MAX_SKILL_LEVEL) {
    return 0;
  }
  return 15 + 25 * safeLevel;
}

export function formatSkillLevelBadgeSegment(
  level: number,
  xp?: number
): string {
  const safeLv = clampSkillLevel(level);
  if (safeLv >= MAX_SKILL_LEVEL) {
    return `Lv.${safeLv} (MAX)`;
  }
  if (typeof xp === 'number' && Number.isFinite(xp)) {
    const req = computeSkillXpToNextLevel(safeLv);
    return `Lv.${safeLv} (XP ${Math.floor(Math.max(0, xp))}/${req})`;
  }
  return `Lv.${safeLv}`;
}

/**
 * Self-buff attribute multiplier (`1.50` = `+50%` at `Lv. 1` -> `1.77` = `+77%` at `Lv. 10`)
 * and minimum flat bonus (`+3` at `Lv. 1` -> `+6` at `Lv. 10`) for `Roar`, `Tough`, `Clever`, and `Scud`.
 */
export function computeSelfBuffAttrRatio(level = 1): number {
  const delta = clampSkillLevel(level) - 1;
  return Number((1.5 + 0.03 * delta).toFixed(4));
}

export function computeSelfBuffAttrBonusPercent(level = 1): number {
  return 50 + 3 * (clampSkillLevel(level) - 1);
}

export function computeSelfBuffAttrMinBonus(level = 1): number {
  return 3 + Math.floor((clampSkillLevel(level) - 1) / 3);
}

/**
 * `Shield` (`鐵壁`) physical defense bonus ratio (`0.50` = `+50%` at `Lv. 1` -> `0.77` = `+77%` at `Lv. 10`)
 * and minimum flat bonus (`+5` at `Lv. 1` -> `+9` at `Lv. 10`).
 */
export function computeScaledShieldBonusRatio(level = 1): number {
  const delta = clampSkillLevel(level) - 1;
  return Number((0.5 + 0.03 * delta).toFixed(4));
}

export function computeScaledShieldBonusPercent(level = 1): number {
  return 50 + 3 * (clampSkillLevel(level) - 1);
}

export function computeScaledShieldMinBonus(level = 1): number {
  return 5 + Math.floor((clampSkillLevel(level) - 1) / 2);
}

