export type WarSkillStatusEffectId = 'bleeding' | 'armor_break' | 'faint' | 'blind';

export interface WarSkillStatusProc {
  readonly effectId: WarSkillStatusEffectId;
  readonly chance: number;
  readonly minTurns: number;
  readonly maxTurns: number;
}

export type WarSkillSelfBuffEffectId = 'invisible' | 'roar' | 'tough';

export interface WarSkillSelfBuff {
  readonly effectId: WarSkillSelfBuffEffectId;
  readonly turns: number;
}

export interface WarSkillKnockbackProc {
  readonly chance: number;
  readonly distance: number;
}

export interface WarSkillDefinition {
  readonly skillId: string;
  readonly nameEn: string;
  readonly nameZh: string;
  readonly spriteKey: string;
  readonly projectileSpriteKey?: string;
  readonly vfxId: SkillVfxId;
  readonly spCost: number;
  readonly timeCost: number;
  readonly targeting: WarSkillTargeting;
  readonly range?: number;
  readonly isShadowBlink?: boolean;
  readonly bonusCritChance?: number;
  readonly scalingStat: WarSkillScalingStat;
  readonly dice: WeaponDice;
  readonly strMultiplier: number;
  readonly statusProc?: WarSkillStatusProc;
  readonly selfBuff?: WarSkillSelfBuff;
  readonly knockback?: WarSkillKnockbackProc;
  readonly descriptionEn: string;
  readonly descriptionZh: string;
}

const WAR_SKILL_REGISTRY = new Map<string, WarSkillDefinition>();

export function registerWarSkill(skill: WarSkillDefinition): void {
  WAR_SKILL_REGISTRY.set(skill.skillId, skill);
}

export function getWarSkillById(skillId: string): WarSkillDefinition | undefined {
  return WAR_SKILL_REGISTRY.get(skillId);
}

export function getAllWarSkills(): readonly WarSkillDefinition[] {
  return Array.from(WAR_SKILL_REGISTRY.values());
}

export function getScaledWarSkillFlatBonus(skill: WarSkillDefinition, level = 1): number {
  return skill.dice.count > 0 ? clampSkillLevel(level) - 1 : 0;
}

export function getScaledWarSkillStrMultiplier(skill: WarSkillDefinition, level = 1): number {
  if (skill.strMultiplier <= 0) {
    return 0;
  }
  const delta = clampSkillLevel(level) - 1;
  return Number((skill.strMultiplier + 0.05 * delta).toFixed(4));
}

export function getScaledWarSkillBonusCritChance(skill: WarSkillDefinition, level = 1): number {
  if (!skill.bonusCritChance) {
    return 0;
  }
  return skill.bonusCritChance + 2 * (clampSkillLevel(level) - 1);
}

export function getScaledWarSkillKnockbackChance(skill: WarSkillDefinition, level = 1): number {
  if (!skill.knockback) {
    return 0;
  }
  const delta = clampSkillLevel(level) - 1;
  return Math.min(1, Number((skill.knockback.chance + 0.04 * delta).toFixed(4)));
}

export function getScaledWarSkillSelfBuffTurns(skill: WarSkillDefinition, level = 1): number {
  if (!skill.selfBuff) {
    return 0;
  }
  return skill.selfBuff.turns + Math.floor((clampSkillLevel(level) - 1) / 2);
}

export function getScaledWarSkillStatusProc(
  skill: WarSkillDefinition,
  level = 1
): WarSkillStatusProc | undefined {
  if (!skill.statusProc) {
    return undefined;
  }
  const delta = clampSkillLevel(level) - 1;
  const base = skill.statusProc;
  switch (base.effectId) {
    case 'bleeding':
    case 'armor_break':
      return {
        effectId: base.effectId,
        chance: Math.min(1, Number((base.chance + 0.03 * delta).toFixed(4))),
        minTurns: base.minTurns + Math.floor(delta / 3),
        maxTurns: base.maxTurns + Math.floor(delta / 3),
      };
    case 'faint':
      return {
        effectId: base.effectId,
        chance: Math.min(1, Number((base.chance + 0.02 * delta).toFixed(4))),
        minTurns: base.minTurns + Math.floor(delta / 5),
        maxTurns: base.maxTurns + Math.floor(delta / 4),
      };
    case 'blind':
      return {
        effectId: base.effectId,
        chance: Math.min(1, Number((base.chance + 0.03 * delta).toFixed(4))),
        minTurns: base.minTurns + Math.floor(delta / 4),
        maxTurns: base.maxTurns + Math.floor(delta / 4),
      };
  }
}

/**
 * Rolls weapon-independent raw physical damage for a War Skill at `level` (`1..10`):
 * `Dice + (level - 1) + round(STR * (strMultiplier + 0.05 * (level - 1)))`.
 */
export function rollWarSkillRawDamage(
  skill: WarSkillDefinition,
  effectiveStr: number,
  rng?: SeededRNG,
  level = 1
): number {
  const rolledDice = rollWeaponDice(skill.dice, rng);
  const flatBonus = getScaledWarSkillFlatBonus(skill, level);
  const strPart = Math.round(effectiveStr * getScaledWarSkillStrMultiplier(skill, level));
  return Math.max(1, rolledDice + flatBonus + strPart);
}

export function getLocalizedWarSkillName(
  skill: WarSkillDefinition,
  lang: 'en' | 'zh-TW'
): string {
  return lang === 'zh-TW' ? skill.nameZh : skill.nameEn;
}

export function getLocalizedWarSkillBadge(
  skill: WarSkillDefinition,
  lang: 'en' | 'zh-TW',
  level?: number,
  xp?: number
): string {
  const statLabel =
    lang === 'zh-TW'
      ? skill.scalingStat === 'str'
        ? '力量'
        : skill.scalingStat === 'agi'
          ? '敏捷'
          : '體質'
      : skill.scalingStat.toUpperCase();
  const lvPart =
    typeof level === 'number' ? ` · ${formatSkillLevelBadgeSegment(level, xp)}` : '';
  return lang === 'zh-TW'
    ? `戰技${lvPart} · ${skill.spCost} SP · ${statLabel}`
    : `War Skill${lvPart} · ${skill.spCost} SP · ${statLabel}`;
}

function formatScaledFormulaPrefix(dice: WeaponDice, flatBonus: number): string {
  const base = `${dice.count}d${dice.sides}`;
  return flatBonus > 0 ? `${base} + ${flatBonus}` : base;
}

export function getLocalizedWarSkillDescription(
  skill: WarSkillDefinition,
  lang: 'en' | 'zh-TW',
  level = 1
): string {
  const safeLv = clampSkillLevel(level);
  if (safeLv === 1) {
    return lang === 'zh-TW' ? skill.descriptionZh : skill.descriptionEn;
  }
  const flat = getScaledWarSkillFlatBonus(skill, safeLv);
  const mult = getScaledWarSkillStrMultiplier(skill, safeLv).toFixed(2);
  const diceStr = skill.dice.count > 0 ? formatScaledFormulaPrefix(skill.dice, flat) : '';
  const proc = getScaledWarSkillStatusProc(skill, safeLv);

  switch (skill.skillId) {
    case 'bite': {
      const pct = Math.round((proc?.chance ?? 0.4) * 100);
      return lang === 'zh-TW'
        ? `猛力張口噬咬相鄰目標，造成基於力量（${diceStr} + ${mult}×力量，無視手持武器）的物理傷害，並有 ${pct}% 機率附加「流血」（${proc?.minTurns}–${proc?.maxTurns} 回合）。`
        : `Sink your jaws into an adjacent target, dealing ${diceStr} + round(STR × ${mult}) physical damage independent of equipped weapons, with a ${pct}% chance to inflict Bleeding (${proc?.minTurns}–${proc?.maxTurns} turns).`;
    }
    case 'pierce': {
      const pct = Math.round((proc?.chance ?? 0.4) * 100);
      return lang === 'zh-TW'
        ? `貫穿刺擊相鄰目標，造成基於力量（${diceStr} + ${mult}×力量，無視手持武器）的物理傷害，並有 ${pct}% 機率附加「破甲」（${proc?.minTurns}–${proc?.maxTurns} 回合，物理防禦減半）。`
        : `Drive a piercing thrust into an adjacent target, dealing ${diceStr} + round(STR × ${mult}) physical damage independent of equipped weapons, with a ${pct}% chance to inflict Armor Break (${proc?.minTurns}–${proc?.maxTurns} turns, halving DEF).`;
    }
    case 'bash': {
      const pct = Math.round((proc?.chance ?? 0.3) * 100);
      return lang === 'zh-TW'
        ? `沉重猛擊相鄰目標，造成基於力量（${diceStr} + ${mult}×力量，無視手持武器）的物理傷害，並有 ${pct}% 機率附加「昏厥」（${proc?.minTurns}–${proc?.maxTurns} 回合，對已昏厥目標不疊加）。`
        : `Deliver a crushing blow to an adjacent target, dealing ${diceStr} + round(STR × ${mult}) physical damage independent of equipped weapons, with a ${pct}% chance to inflict Faint (${proc?.minTurns}–${proc?.maxTurns} turns; does not stack on already fainted targets).`;
    }
    case 'hide': {
      const turns = getScaledWarSkillSelfBuffTurns(skill, safeLv);
      return lang === 'zh-TW'
        ? `屏息斂跡融入暗影之中，使自身獲得 ${turns} 回合「隱形」狀態。`
        : `Blend silently into the dungeon shadows, granting yourself Invisible for ${turns} turns.`;
    }
    case 'roar': {
      const turns = getScaledWarSkillSelfBuffTurns(skill, safeLv);
      const pct = computeSelfBuffAttrBonusPercent(safeLv);
      const minB = computeSelfBuffAttrMinBonus(safeLv);
      return lang === 'zh-TW'
        ? `爆發震懾全場的狂猛戰吼，在 ${turns} 回合內使力量（STR）提升 ${pct}%（至少 +${minB}）。`
        : `Unleash a thunderous battle roar, increasing STR by ${pct}% (min +${minB}) for ${turns} full turns.`;
    }
    case 'tough': {
      const turns = getScaledWarSkillSelfBuffTurns(skill, safeLv);
      const pct = computeSelfBuffAttrBonusPercent(safeLv);
      const minB = computeSelfBuffAttrMinBonus(safeLv);
      return lang === 'zh-TW'
        ? `鼓盪全身氣血凝練鋼鐵般的體魄，在 ${turns} 回合內使體質（CON）提升 ${pct}%（至少 +${minB}）。`
        : `Brace your body with unyielding fortitude, increasing CON by ${pct}% (min +${minB}) for ${turns} full turns.`;
    }
    case 'charge': {
      const kbPct = Math.round(getScaledWarSkillKnockbackChance(skill, safeLv) * 100);
      return lang === 'zh-TW'
        ? `朝 5 格內的目標或位置猛烈衝鋒，撞擊路徑上第一個目標造成基於力量（${diceStr} + ${mult}×力量）的物理傷害，並有 ${kbPct}% 機率將目標擊退 1 格並踏入其位置。`
        : `Bull-rush up to 5 tiles toward a target or tile, slamming the first foe for ${diceStr} + round(STR × ${mult}) physical damage with a ${kbPct}% chance to knock them back 1 tile and advance into their space.`;
    }
    case 'shadow_strike': {
      const critB = getScaledWarSkillBonusCritChance(skill, safeLv);
      const pct = Math.round((proc?.chance ?? 0.25) * 100);
      return lang === 'zh-TW'
        ? `化作暗影瞬步潛至 5 格內目標身後（或空地），發動致命奇襲造成基於力量（${diceStr} + ${mult}×力量）的物理傷害（暴擊率額外 +${critB}%），並有 ${pct}% 機率附加「失明」（${proc?.minTurns}–${proc?.maxTurns} 回合）。`
        : `Blink through shadow beside or behind a target up to 5 tiles away (or onto an open tile), striking for ${diceStr} + round(STR × ${mult}) physical damage with +${critB}% bonus Crit Chance and a ${pct}% chance to inflict Blind (${proc?.minTurns}–${proc?.maxTurns} turns).`;
    }
    default:
      return lang === 'zh-TW' ? skill.descriptionZh : skill.descriptionEn;
  }
}

