export type MagicSkillTargeting = 'adjacent' | 'self' | 'ranged_tile' | 'directional';
export type MagicSkillScalingStat = 'int' | 'wis';
export type MagicSkillSelfBuffEffectId = 'clever' | 'shield' | 'scud';

export interface MagicSkillSelfBuff {
  readonly effectId: MagicSkillSelfBuffEffectId;
  readonly turns: number;
}

export type MagicSkillStatusEffectId = 'bleeding' | 'armor_break' | 'faint' | 'blind';

export interface MagicSkillStatusProc {
  readonly effectId: MagicSkillStatusEffectId;
  readonly chance: number;
  readonly minTurns: number;
  readonly maxTurns: number;
}

export interface MagicSkillDefinition {
  readonly skillId: string;
  readonly nameEn: string;
  readonly nameZh: string;
  readonly spriteKey: string;
  readonly projectileSpriteKey?: string;
  readonly piercesLine?: boolean;
  readonly vfxId: SkillVfxId;
  readonly mpCost: number;
  readonly timeCost: number;
  readonly targeting: MagicSkillTargeting;
  readonly range?: number;
  readonly scalingStat: MagicSkillScalingStat;
  readonly dice: WeaponDice;
  readonly intMultiplier: number;
  readonly selfBuff?: MagicSkillSelfBuff;
  readonly statusProcs?: readonly MagicSkillStatusProc[];
  readonly descriptionEn: string;
  readonly descriptionZh: string;
}

const MAGIC_SKILL_REGISTRY = new Map<string, MagicSkillDefinition>();

export function registerMagicSkill(skill: MagicSkillDefinition): void {
  MAGIC_SKILL_REGISTRY.set(skill.skillId, skill);
}

export function getMagicSkillById(skillId: string): MagicSkillDefinition | undefined {
  return MAGIC_SKILL_REGISTRY.get(skillId);
}

export function getAllMagicSkills(): readonly MagicSkillDefinition[] {
  return Array.from(MAGIC_SKILL_REGISTRY.values());
}

export function getScaledMagicSkillFlatBonus(skill: MagicSkillDefinition, level = 1): number {
  return skill.dice.count > 0 ? clampSkillLevel(level) - 1 : 0;
}

export function getScaledMagicSkillIntMultiplier(skill: MagicSkillDefinition, level = 1): number {
  if (skill.intMultiplier <= 0) {
    return 0;
  }
  const delta = clampSkillLevel(level) - 1;
  return Number((skill.intMultiplier + 0.05 * delta).toFixed(4));
}

export function getScaledMagicSkillSelfBuffTurns(skill: MagicSkillDefinition, level = 1): number {
  if (!skill.selfBuff) {
    return 0;
  }
  return skill.selfBuff.turns + Math.floor((clampSkillLevel(level) - 1) / 2);
}

export function getScaledMagicSkillStatusProcs(
  skill: MagicSkillDefinition,
  level = 1
): readonly MagicSkillStatusProc[] {
  if (!skill.statusProcs || skill.statusProcs.length === 0) {
    return [];
  }
  const delta = clampSkillLevel(level) - 1;
  return skill.statusProcs.map((proc) => ({
    effectId: proc.effectId,
    chance: Math.min(1, Number((proc.chance + 0.03 * delta).toFixed(4))),
    minTurns: proc.minTurns + Math.floor(delta / 4),
    maxTurns: proc.maxTurns + Math.floor(delta / 4),
  }));
}

/**
 * Rolls weapon-independent raw magic damage for a Magic Skill at `level` (`1..10`):
 * `Dice + (level - 1) + round(INT * (intMultiplier + 0.05 * (level - 1))) + bonusDamage`.
 */
export function rollMagicSkillRawDamage(
  skill: MagicSkillDefinition,
  effectiveInt: number,
  rng?: SeededRNG,
  bonusDamage = 0,
  level = 1
): number {
  const rolledDice = rollWeaponDice(skill.dice, rng);
  const flatBonus = getScaledMagicSkillFlatBonus(skill, level);
  const intPart = Math.round(effectiveInt * getScaledMagicSkillIntMultiplier(skill, level));
  return Math.max(1, rolledDice + flatBonus + intPart + bonusDamage);
}

export function getLocalizedMagicSkillName(
  skill: MagicSkillDefinition,
  lang: 'en' | 'zh-TW'
): string {
  return lang === 'zh-TW' ? skill.nameZh : skill.nameEn;
}

export function getLocalizedMagicSkillBadge(
  skill: MagicSkillDefinition,
  lang: 'en' | 'zh-TW',
  level?: number,
  xp?: number
): string {
  const statLabel =
    lang === 'zh-TW'
      ? skill.scalingStat === 'int'
        ? '智力'
        : '智慧'
      : skill.scalingStat.toUpperCase();
  const lvPart =
    typeof level === 'number' ? ` · ${formatSkillLevelBadgeSegment(level, xp)}` : '';
  return lang === 'zh-TW'
    ? `魔法${lvPart} · ${skill.mpCost} MP · ${statLabel}`
    : `Magic Skill${lvPart} · ${skill.mpCost} MP · ${statLabel}`;
}

export function getLocalizedMagicSkillDescription(
  skill: MagicSkillDefinition,
  lang: 'en' | 'zh-TW',
  level = 1
): string {
  const safeLv = clampSkillLevel(level);
  if (safeLv === 1) {
    return lang === 'zh-TW' ? skill.descriptionZh : skill.descriptionEn;
  }
  const flat = getScaledMagicSkillFlatBonus(skill, safeLv);
  const mult = getScaledMagicSkillIntMultiplier(skill, safeLv).toFixed(2);
  const diceStr = skill.dice.count > 0 ? formatScaledFormulaPrefix(skill.dice, flat) : '';

  switch (skill.skillId) {
    case 'acid':
      return lang === 'zh-TW'
        ? `向相鄰格潑灑強腐蝕性魔力酸液，必中目標並造成基於智力（${diceStr} + ${mult}×智力）的魔法傷害（受魔防減免）。`
        : `Splash corrosive arcane acid onto an adjacent tile, always hitting for ${diceStr} + round(INT × ${mult}) magic damage mitigated by MDEF.`;
    case 'clever': {
      const turns = getScaledMagicSkillSelfBuffTurns(skill, safeLv);
      const pct = computeSelfBuffAttrBonusPercent(safeLv);
      const minB = computeSelfBuffAttrMinBonus(safeLv);
      return lang === 'zh-TW'
        ? `凝聚靈動慧黠的奧術靈光，使自身在 ${turns} 回合內智力提升 ${pct}%（至少 +${minB}）。`
        : `Sharpen your mind with cunning arcane insight, increasing INT by ${pct}% (minimum +${minB}) for ${turns} full turns.`;
    }
    case 'shield': {
      const turns = getScaledMagicSkillSelfBuffTurns(skill, safeLv);
      const pct = computeScaledShieldBonusPercent(safeLv);
      const minB = computeScaledShieldMinBonus(safeLv);
      return lang === 'zh-TW'
        ? `凝聚厚重磐石魔力護盾，使自身在 ${turns} 回合內物理防禦（DEF）提升 ${pct}%（至少 +${minB}）。`
        : `Surround yourself with an arcane stone-iron barrier, increasing DEF by ${pct}% (minimum +${minB}) for ${turns} full turns.`;
    }
    case 'scud': {
      const turns = getScaledMagicSkillSelfBuffTurns(skill, safeLv);
      const pct = computeSelfBuffAttrBonusPercent(safeLv);
      const minB = computeSelfBuffAttrMinBonus(safeLv);
      return lang === 'zh-TW'
        ? `凝聚疾風魔力繚繞全身，使自身在 ${turns} 回合內敏捷（AGI）提升 ${pct}%（至少 +${minB}）。`
        : `Cloak yourself in fleet wind mana, increasing AGI by ${pct}% (minimum +${minB}) for ${turns} full turns.`;
    }
    case 'rock_missile':
      return lang === 'zh-TW'
        ? `凝聚魔力發射疾速飛岩沿直線飛行最多 8 格（亦可對自身施放），命中路徑上第一個目標並造成基於智力（${diceStr} + ${mult}×智力）的魔法傷害（受魔防減免）。`
        : `Hurl a jagged arcane boulder up to 8 tiles (or onto yourself), striking the first target in its path for ${diceStr} + round(INT × ${mult}) magic damage mitigated by MDEF.`;
    case 'rock_pierce':
      return lang === 'zh-TW'
        ? `震裂大地使尖銳岩石堆沿自身至目標點的直線（最遠 5 格，亦可對自身施放）連續突起，對路徑上所有目標造成基於智力（${diceStr} + ${mult}×智力）的魔法傷害（受魔防減免）。`
        : `Erupt a line of jagged stone piles from yourself to the target tile (up to 5 tiles, or onto yourself), dealing ${diceStr} + round(INT × ${mult}) magic damage mitigated by MDEF to every target along the path.`;
    case 'fireball':
      return lang === 'zh-TW'
        ? `發射熾熱火球沿直線飛行最多 8 格（亦可對自身施放），命中路徑上第一個目標並造成基於智力（${diceStr} + ${mult}×智力）的火焰魔法傷害（受魔防減免）。`
        : `Hurl a blazing fireball up to 8 tiles (or onto yourself), exploding on the first target in its path for ${diceStr} + round(INT × ${mult}) magic damage mitigated by MDEF.`;
    case 'abyssal_eclipse': {
      const procs = getScaledMagicSkillStatusProcs(skill, safeLv);
      const blindP = procs[0];
      const breakP = procs[1];
      const pct = Math.round((blindP?.chance ?? 0.5) * 100);
      return lang === 'zh-TW'
        ? `撕裂深淵暗影沿自身至目標點的直線（最遠 6 格，亦可對自身施放）綻放冥蝕裂隙，對路徑上所有目標造成基於智力（${diceStr} + ${mult}×智力）的魔法傷害（受魔防減免），並各有 ${pct}% 機率附加「失明」（${blindP?.minTurns}–${blindP?.maxTurns} 回合）與「破甲」（${breakP?.minTurns}–${breakP?.maxTurns} 回合）。`
        : `Tear open a line-piercing abyssal eclipse rift up to 6 tiles (or onto yourself), dealing ${diceStr} + round(INT × ${mult}) magic damage mitigated by MDEF to every target along the path, with independent ${pct}% chances to inflict Blind (${blindP?.minTurns}–${blindP?.maxTurns} turns) and Armor Break (${breakP?.minTurns}–${breakP?.maxTurns} turns).`;
    }
    default:
      return lang === 'zh-TW' ? skill.descriptionZh : skill.descriptionEn;
  }
}

