// Passive Skill Registry (`Lv. 1`–`10` Scaling)
// =========================================================================

export interface PassiveSkillDefinition {
  readonly skillId: string;
  readonly nameEn: string;
  readonly nameZh: string;
  readonly spriteKey: string;
}

const PASSIVE_SKILL_REGISTRY = new Map<string, PassiveSkillDefinition>();

export function registerPassiveSkill(skill: PassiveSkillDefinition): void {
  PASSIVE_SKILL_REGISTRY.set(skill.skillId, skill);
}

export function getPassiveSkillById(skillId: string): PassiveSkillDefinition | undefined {
  return PASSIVE_SKILL_REGISTRY.get(skillId);
}

export function getAllPassiveSkills(): readonly PassiveSkillDefinition[] {
  return Array.from(PASSIVE_SKILL_REGISTRY.values());
}

export function getLocalizedPassiveSkillName(
  skill: PassiveSkillDefinition,
  lang: 'en' | 'zh-TW'
): string {
  return lang === 'zh-TW' ? skill.nameZh : skill.nameEn;
}

/**
 * `Fledgling` (`雛羽`) EXP bonus ratio (`0.05` = `+5%` at `Lv. 1` -> `0.14` = `+14%` at `Lv. 10`):
 * `5% + 1% * (level - 1)`.
 */
export function computeFledglingXpBonusPercent(level = 1): number {
  return 5 + (clampSkillLevel(level) - 1);
}

export function computeFledglingXpBonusRatio(level = 1): number {
  return Number((computeFledglingXpBonusPercent(level) / 100).toFixed(4));
}

/**
 * `Scavenger` (`食腐`) Rotten Food Satiety recovery percentage (`60%` at `Lv. 1` -> `100%` at `Lv. 10`):
 * `round(60 + 40 * (level - 1) / 9)`.
 */
export function computeScavengerSatietyPercent(level = 1): number {
  const delta = clampSkillLevel(level) - 1;
  return Math.round(60 + (40 * delta) / 9);
}

export function computeScavengerRottenSatiety(baseSatiety: number, level = 1): number {
  const pct = computeScavengerSatietyPercent(level);
  return Math.max(1, Math.round(baseSatiety * (pct / 100)));
}

