export function getAnySkillLocalizedName(skillId: string, lang: 'en' | 'zh-TW'): string {
  const war = getWarSkillById(skillId);
  if (war) return getLocalizedWarSkillName(war, lang);
  const magic = getMagicSkillById(skillId);
  if (magic) return getLocalizedMagicSkillName(magic, lang);
  const passive = getPassiveSkillById(skillId);
  if (passive) return getLocalizedPassiveSkillName(passive, lang);
  return skillId;
}
