  public toggleSaveConfirmSelection(): void {
    if (this.activeModal !== 'save_confirm') {
      return;
    }
    this.selectedSaveConfirmChoice = this.selectedSaveConfirmChoice === 'yes' ? 'no' : 'yes';
    this.renderSaveConfirmModal();
  }

  public confirmSaveChoice(world?: GameWorld, forceChoice?: 'yes' | 'no'): void {
    if (this.activeModal !== 'save_confirm') {
      return;
    }
    const targetWorld = world ?? this.currentWorld;
    const choice = forceChoice ?? this.selectedSaveConfirmChoice;
    if (choice === 'yes') {
      if (targetWorld) {
        this.config.saveManager?.saveGame(targetWorld);
      }
      this.openTitleScreen();
      this.config.onReturnToTitleScreen?.();
      this.config.onModalStateChange?.();
    } else {
      this.closeModal(targetWorld);
      this.config.onModalStateChange?.();
    }
  }

  private renderSaveConfirmModal(): void {
    const t = TRANSLATIONS[this.currentLanguage];
    if (this.config.saveConfirmTitleEl) {
      this.config.saveConfirmTitleEl.textContent = t.saveUI.confirmModalTitle;
    }
    if (this.config.saveConfirmSubtitleEl) {
      this.config.saveConfirmSubtitleEl.textContent = t.saveUI.confirmModalSubtitle;
    }
    const body = this.config.saveConfirmBodyEl;
    if (!body) {
      return;
    }
    body.innerHTML = '';

    const promptDiv = document.createElement('div');
    promptDiv.className = 'save-confirm-prompt';
    promptDiv.textContent = t.saveUI.confirmPrompt;
    body.appendChild(promptDiv);

    const btnGroup = document.createElement('div');
    btnGroup.className = 'save-confirm-buttons';

    const yesBtn = document.createElement('button');
    yesBtn.type = 'button';
    yesBtn.id = 'save-confirm-yes-btn';
    yesBtn.className =
      this.selectedSaveConfirmChoice === 'yes'
        ? 'save-confirm-btn selected'
        : 'save-confirm-btn';
    yesBtn.textContent = t.saveUI.yesButton;
    yesBtn.addEventListener('mouseenter', () => {
      if (this.selectedSaveConfirmChoice !== 'yes') {
        this.selectedSaveConfirmChoice = 'yes';
        this.renderSaveConfirmModal();
      }
    });
    yesBtn.addEventListener('click', () => {
      this.confirmSaveChoice(this.currentWorld, 'yes');
    });

    const noBtn = document.createElement('button');
    noBtn.type = 'button';
    noBtn.id = 'save-confirm-no-btn';
    noBtn.className =
      this.selectedSaveConfirmChoice === 'no'
        ? 'save-confirm-btn selected'
        : 'save-confirm-btn';
    noBtn.textContent = t.saveUI.noButton;
    noBtn.addEventListener('mouseenter', () => {
      if (this.selectedSaveConfirmChoice !== 'no') {
        this.selectedSaveConfirmChoice = 'no';
        this.renderSaveConfirmModal();
      }
    });
    noBtn.addEventListener('click', () => {
      this.confirmSaveChoice(this.currentWorld, 'no');
    });

    btnGroup.appendChild(yesBtn);
    btnGroup.appendChild(noBtn);
    body.appendChild(btnGroup);
  }

