  /**
   * Binds, rebinds, or toggles unbind on `slot` (`'0'`–`'9'`) for the currently highlighted
   * skill inside `'war_skills'` or `'magic_skills'` (`0` timeline ticks).
   */
  public bindSelectedModalSkillHotkey(
    world: GameWorld,
    slot: HotkeySlot
  ): 'bound' | 'unbound' | 'invalid' {
    if (this.activeModal === 'war_skills') {
      const skills = world.player.getLearnedWarSkills();
      if (skills.length === 0) {
        return 'invalid';
      }
      this.selectedWarSkillIndex = Math.max(
        0,
        Math.min(skills.length - 1, this.selectedWarSkillIndex)
      );
      const chosen = skills[this.selectedWarSkillIndex];
      const res = world.player.toggleOrBindSkillHotkey(slot, 'war', chosen.skillId);
      this.renderWarSkillsModal(world);
      return res;
    }

    if (this.activeModal === 'magic_skills') {
      const skills = world.player.getLearnedMagicSkills();
      if (skills.length === 0) {
        return 'invalid';
      }
      this.selectedMagicSkillIndex = Math.max(
        0,
        Math.min(skills.length - 1, this.selectedMagicSkillIndex)
      );
      const chosen = skills[this.selectedMagicSkillIndex];
      const res = world.player.toggleOrBindSkillHotkey(slot, 'magic', chosen.skillId);
      this.renderMagicSkillsModal(world);
      return res;
    }

    return 'invalid';
  }

