  /**
   * Returns true when the currently open modal uses a 2-column row-major selection grid.
   * Note: Equipment Stage 1 ('equipment') intentionally remains 1-column for its fixed 9 slots.
   */
  public isTwoColumnActiveModal(): boolean {
    switch (this.activeModal) {
      case 'actions':
      case 'tutorial_select':
      case 'inventory':
      case 'pickup':
      case 'drop':
      case 'eat':
      case 'quaff':
      case 'read_scroll':
      case 'identify_item':
      case 'enchant_armor':
      case 'throw':
      case 'craft_recipes':
      case 'craft_assemble':
      case 'equip_select':
      case 'war_skills':
      case 'magic_skills':
        return true;
      default:
        return false;
    }
  }

