  private renderInventorySubTabsBar(world: GameWorld): void {
    const tabsEl = this.config.itemModalTabsEl;
    if (!tabsEl) {
      return;
    }
    if (this.activeModal !== 'inventory') {
      tabsEl.classList.add('hidden');
      return;
    }
    tabsEl.classList.remove('hidden');
    if (typeof document === 'undefined') {
      return;
    }
    tabsEl.innerHTML = '';
    const t = TRANSLATIONS[this.currentLanguage];
    const headerTabs = this.getFormattedInventoryHeaderTabs(world);
    for (const tab of headerTabs) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = tab.active ? 'item-subtab-btn active' : 'item-subtab-btn';
      btn.dataset.subtab = tab.id;
      btn.textContent = tab.label;
      btn.addEventListener('click', () => {
        if (this.inventorySubTab !== tab.id) {
          this.switchInventorySubTab(world, tab.id);
          this.config.onModalStateChange?.();
        }
      });
      tabsEl.appendChild(btn);
    }
    const hint = document.createElement('span');
    hint.className = 'item-subtab-hint';
    hint.textContent = t.itemModalsUI.subTabSwitchHint;
    tabsEl.appendChild(hint);
  }

  private renderWarSkillsModal(world: GameWorld, scrollIntoView = false): void {
    this.config.itemModalTabsEl?.classList.add('hidden');
    this.config.craftSidePanelEl?.classList.add('hidden');
    this.config.itemModalStackEl?.classList.remove('craft-mode-wide');
    this.config.itemModalBodyEl?.classList.add('two-col-grid');

    const rows = this.getFormattedWarSkillRows(world);
    this.renderItemDescriptionTab(world);

    const t = TRANSLATIONS[this.currentLanguage];
    const p = world.player;
    if (this.config.itemModalTitleEl) {
      this.config.itemModalTitleEl.textContent = `${t.itemModalsUI.warSkillsTitle} (${t.stats.sp}: ${p.stats.sp}/${p.stats.maxSp})`;
    }
    if (this.config.itemModalSubtitleEl) {
      this.config.itemModalSubtitleEl.textContent = t.itemModalsUI.warSkillsSubtitle;
    }

    const body = this.config.itemModalBodyEl;
    if (!body || typeof document === 'undefined') {
      return;
    }
    const previousScrollTop = typeof body.scrollTop === 'number' ? body.scrollTop : 0;
    body.innerHTML = '';

    if (rows.length === 0) {
      const emptyEl = document.createElement('div');
      emptyEl.className = 'item-modal-empty';
      emptyEl.textContent = t.itemModalsUI.warSkillsEmpty;
      body.appendChild(emptyEl);
      return;
    }

    let selectedRowEl: HTMLElement | null = null;
    rows.forEach((rowInfo, idx) => {
      const row = document.createElement('div');
      const classes = ['item-modal-row'];
      if (rowInfo.selected) {
        classes.push('selected');
        selectedRowEl = row;
      }
      if (!rowInfo.canAfford) classes.push('dimmed');
      row.className = classes.join(' ');
      row.dataset.skillId = rowInfo.skillId;

      const mainGroup = document.createElement('div');
      mainGroup.className = 'item-modal-main';

      const iconImg = document.createElement('img');
      iconImg.className = 'item-modal-icon';
      iconImg.dataset.spriteKey = rowInfo.spriteKey;
      const dataUrl = this.sprites.getSpriteDataUrl(rowInfo.spriteKey as never);
      if (dataUrl) {
        iconImg.src = dataUrl;
      }
      iconImg.alt = rowInfo.label;

      const labelSpan = document.createElement('span');
      labelSpan.className = 'item-modal-label';
      labelSpan.textContent = rowInfo.label;

      mainGroup.appendChild(iconImg);
      mainGroup.appendChild(labelSpan);

      const rightGroup = document.createElement('div');
      rightGroup.className = 'item-modal-right';
      const badgeSpan = document.createElement('span');
      badgeSpan.className = 'item-modal-weight';
      badgeSpan.textContent = `[${rowInfo.badge}]`;
      rightGroup.appendChild(badgeSpan);

      row.appendChild(mainGroup);
      row.appendChild(rightGroup);

      row.addEventListener('mouseenter', () => {
        if (this.selectedWarSkillIndex !== idx) {
          this.selectedWarSkillIndex = idx;
          this.renderWarSkillsModal(world);
        }
      });

      row.addEventListener('click', () => {
        this.selectedWarSkillIndex = idx;
        this.confirmItemModalSelection(world, false);
        this.config.onModalStateChange?.();
      });

      body.appendChild(row);
    });
    if (typeof body.scrollTop === 'number') {
      body.scrollTop = previousScrollTop;
    }
    if (scrollIntoView) {
      scrollModalRowIntoView(body, selectedRowEl);
    }
  }

