  public getFormattedEnchantArmorRows(world: GameWorld): FormattedEnchantArmorRow[] {
    const t = TRANSLATIONS[this.currentLanguage];
    const choices = world.getEquippedArmorChoices();
    if (choices.length === 0) {
      this.selectedEnchantArmorIndex = 0;
      return [];
    }
    this.selectedEnchantArmorIndex = Math.max(
      0,
      Math.min(choices.length - 1, this.selectedEnchantArmorIndex)
    );
    return choices.map((entry, idx) => {
      const slotLabel = t.equipmentSlots[entry.slot];
      const localizedName = localizeItemDisplayName(this.currentLanguage, entry.item.name);
      return {
        slot: entry.slot,
        slotLabel,
        spriteKey: world.getItemEffectiveSpriteKey(entry.item),
        label: `[${slotLabel}] ${localizedName}`,
        statBadge: entry.item.getStatBadge(this.currentLanguage),
        weightLabel: `(${entry.item.weight} ${t.itemModalsUI.weightUnit})`,
        selected: idx === this.selectedEnchantArmorIndex,
      };
    });
  }

