import { Tile } from './Tile';
import { ALL_DIRECTIONS, DoorState, MovementType, Point, TileType } from './types';

export interface Rect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export function rectCenter(rect: Rect): Point {
  return {
    x: Math.floor(rect.x + rect.width / 2),
    y: Math.floor(rect.y + rect.height / 2),
  };
}

export function rectsOverlap(a: Rect, b: Rect, padding = 1): boolean {
  return (
    a.x - padding < b.x + b.width &&
    a.x + a.width + padding > b.x &&
    a.y - padding < b.y + b.height &&
    a.y + a.height + padding > b.y
  );
}

export const DEFAULT_ENEMY_DENSITY = 12;
export const DEFAULT_ENEMY_SPAWN_PROBABILITY = 0.075;
export const MAX_FLOOR_ENEMY_DENSITY = 36;
export const MAX_FLOOR_ENEMY_SPAWN_PROBABILITY = 0.25;

/**
 * Computes the depth-scaled maximum simultaneous enemy cap on `floorNumber` (`>= 1`):
 * enemyDensity(F) = min(36, 12 + 2 * (F - 1))  (12 on Floor 1, 20 on Floor 5, 30 on Floor 10)
 */
export function computeFloorEnemyDensity(floorNumber = 1): number {
  const safeFloor = Math.max(1, Math.floor(floorNumber));
  return Math.min(MAX_FLOOR_ENEMY_DENSITY, DEFAULT_ENEMY_DENSITY + 2 * (safeFloor - 1));
}

/**
 * Computes the depth-scaled per-tick-cycle dynamic enemy spawn probability on `floorNumber` (`>= 1`):
 * enemySpawnProbability(F) = min(0.25, 0.075 + 0.01 * (F - 1))  (7.5% on Floor 1, 11.5% on Floor 5, 16.5% on Floor 10)
 */
export function computeFloorEnemySpawnProbability(floorNumber = 1): number {
  const safeFloor = Math.max(1, Math.floor(floorNumber));
  return Math.min(
    MAX_FLOOR_ENEMY_SPAWN_PROBABILITY,
    Number((DEFAULT_ENEMY_SPAWN_PROBABILITY + 0.01 * (safeFloor - 1)).toFixed(6))
  );
}

export interface DungeonMapOptions {
  readonly enemyDensity?: number;
  readonly enemySpawnProbability?: number;
  readonly floorNumber?: number;
}

/**
 * 2D grid map of Tiles with bounds checking, adjacency queries, enemy spawning density/probability,
 * and ASCII serialization.
 */
export class DungeonMap {
  public readonly width: number;
  public readonly height: number;
  public enemyDensity: number;
  public enemySpawnProbability: number;
  private readonly grid: Tile[][];
  private _rooms: Rect[] = [];

  constructor(
    width: number,
    height: number,
    defaultTileFactory: () => Tile = () => Tile.createWall(),
    options?: DungeonMapOptions
  ) {
    if (width <= 0 || height <= 0) {
      throw new Error(`Invalid DungeonMap dimensions: ${width}x${height}`);
    }
    this.width = width;
    this.height = height;
    const floorNumber = options?.floorNumber ?? 1;
    this.enemyDensity = Math.max(
      0,
      options?.enemyDensity ?? computeFloorEnemyDensity(floorNumber)
    );
    this.enemySpawnProbability = Math.min(
      1,
      Math.max(
        0,
        options?.enemySpawnProbability ?? computeFloorEnemySpawnProbability(floorNumber)
      )
    );
    this.grid = Array.from({ length: height }, () =>
      Array.from({ length: width }, () => defaultTileFactory())
    );
  }

  public inBounds(x: number, y: number): boolean {
    return x >= 0 && x < this.width && y >= 0 && y < this.height;
  }

  public getTile(x: number, y: number): Tile | null {
    if (!this.inBounds(x, y)) {
      return null;
    }
    return this.grid[y][x];
  }

  public setTile(x: number, y: number, tile: Tile): void {
    if (!this.inBounds(x, y)) {
      return;
    }
    this.grid[y][x] = tile;
  }

  public get rooms(): readonly Rect[] {
    return this._rooms;
  }

  public setRooms(rooms: readonly Rect[]): void {
    this._rooms = rooms.map((r) => ({ ...r }));
  }

  private isOpenRoomTerrainAt(x: number, y: number): boolean {
    const tile = this.getTile(x, y);
    if (!tile) {
      return false;
    }
    return (
      tile.type === TileType.FLOOR ||
      tile.type === TileType.WATER ||
      tile.type === TileType.STAIRS_UP ||
      tile.type === TileType.STAIRS_DOWN ||
      tile.type === TileType.PORTAL
    );
  }

  /**
   * Returns true iff `(x, y)` participates in at least one `2x2` open room block (no `WALL` or `DOOR`).
   * `1`-tile-wide tunnels (straight, L-bends, T-junctions, or `+` intersections) never pass this check.
   */
  public isInOpen2x2RoomSpace(x: number, y: number): boolean {
    if (!this.isOpenRoomTerrainAt(x, y)) {
      return false;
    }
    const quadrants: ReadonlyArray<readonly [number, number]> = [
      [-1, -1],
      [1, -1],
      [-1, 1],
      [1, 1],
    ];
    for (const [dx, dy] of quadrants) {
      if (
        this.isOpenRoomTerrainAt(x + dx, y) &&
        this.isOpenRoomTerrainAt(x, y + dy) &&
        this.isOpenRoomTerrainAt(x + dx, y + dy)
      ) {
        return true;
      }
    }
    return false;
  }

  /**
   * Returns true iff `(x, y)` is a plain `FLOOR` tile strictly inside an open room (never in a `1`-tile tunnel).
   */
  public isRoomFloorTile(x: number, y: number): boolean {
    if (this.getTile(x, y)?.type !== TileType.FLOOR) {
      return false;
    }
    if (!this.isInOpen2x2RoomSpace(x, y)) {
      return false;
    }
    if (this._rooms.length > 0) {
      return this._rooms.some(
        (r) => x >= r.x && x < r.x + r.width && y >= r.y && y < r.y + r.height
      );
    }
    return true;
  }

  /**
   * Returns true iff `(x, y)` sits cardinally adjacent to a `DOOR` or a `1`-tile tunnel entrance.
   */
  public isDoorwayOrTunnelThreshold(x: number, y: number): boolean {
    const cardinals: ReadonlyArray<readonly [number, number]> = [
      [0, -1],
      [1, 0],
      [0, 1],
      [-1, 0],
    ];
    for (const [dx, dy] of cardinals) {
      const nx = x + dx;
      const ny = y + dy;
      const nTile = this.getTile(nx, ny);
      if (!nTile) {
        continue;
      }
      if (nTile.type === TileType.DOOR) {
        return true;
      }
      if (nTile.isPassable() && !this.isInOpen2x2RoomSpace(nx, ny)) {
        return true;
      }
    }
    return false;
  }

  public isPassable(x: number, y: number): boolean {
    const tile = this.getTile(x, y);
    return tile !== null && tile.isPassable();
  }

  /**
   * Returns all walkable (passable FLOOR, WATER, STAIRS, PORTAL, or OPEN door) coordinates on the map.
   */
  public getWalkablePoints(): Point[] {
    const points: Point[] = [];
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        if (this.isPassable(x, y)) {
          points.push({ x, y });
        }
      }
    }
    return points;
  }

  /**
   * Returns all coordinates on the map that an actor with `movementType` can occupy.
   */
  public getTraversablePointsFor(movementType: MovementType): Point[] {
    const points: Point[] = [];
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const tile = this.getTile(x, y);
        if (tile && tile.canBeTraversedBy(movementType)) {
          points.push({ x, y });
        }
      }
    }
    return points;
  }

  public isTransparent(x: number, y: number): boolean {
    const tile = this.getTile(x, y);
    return tile !== null && tile.isTransparent();
  }

  /**
   * Returns true if the tile is Either FLOOR or DOOR (open or closed).
   * Useful for verifying map connectivity across closed doors.
   */
  public isTraversableIgnoreClosedDoors(x: number, y: number): boolean {
    const tile = this.getTile(x, y);
    if (!tile) return false;
    return tile.isPassable() || tile.type === TileType.DOOR;
  }

  public getAdjacentPoints(origin: Point, includeDiagonals = true): Point[] {
    const points: Point[] = [];
    for (const dir of ALL_DIRECTIONS) {
      if (!includeDiagonals && dir.dx !== 0 && dir.dy !== 0) {
        continue;
      }
      const nx = origin.x + dir.dx;
      const ny = origin.y + dir.dy;
      if (this.inBounds(nx, ny)) {
        points.push({ x: nx, y: ny });
      }
    }
    return points;
  }

  public carveRect(rect: Rect): void {
    for (let y = rect.y; y < rect.y + rect.height; y++) {
      for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (this.inBounds(x, y)) {
          this.setTile(x, y, Tile.createFloor());
        }
      }
    }
  }

  /**
   * Parses an ASCII map representation for deterministic testing.
   * Legend:
   *   '#' = Wall
   *   '.' = Floor
   *   '+' = Closed Door
   *   '/' = Open Door
   *   '@' = Player spawn on a Floor tile
   */
  public static fromAscii(
    lines: readonly string[],
    options?: DungeonMapOptions
  ): { map: DungeonMap; playerSpawn: Point } {
    if (lines.length === 0 || lines[0].length === 0) {
      throw new Error('ASCII map must have at least 1 non-empty line');
    }
    const height = lines.length;
    const width = Math.max(...lines.map((l) => l.length));
    const map = new DungeonMap(width, height, () => Tile.createWall(), {
      enemyDensity: options?.enemyDensity ?? DEFAULT_ENEMY_DENSITY,
      enemySpawnProbability: options?.enemySpawnProbability ?? 0,
    });
    let playerSpawn: Point = { x: 0, y: 0 };

    for (let y = 0; y < height; y++) {
      const row = lines[y];
      for (let x = 0; x < width; x++) {
        const ch = row[x] ?? '#';
        switch (ch) {
          case '.':
            map.setTile(x, y, Tile.createFloor());
            break;
          case '~':
            map.setTile(x, y, Tile.createWater());
            break;
          case '@':
            map.setTile(x, y, Tile.createFloor());
            playerSpawn = { x, y };
            break;
          case '+':
            map.setTile(x, y, Tile.createDoor(DoorState.CLOSED));
            break;
          case '/':
            map.setTile(x, y, Tile.createDoor(DoorState.OPEN));
            break;
          case '<':
            map.setTile(x, y, Tile.createStairsUp());
            break;
          case '>':
            map.setTile(x, y, Tile.createStairsDown());
            break;
          case 'O':
            map.setTile(x, y, Tile.createPortal());
            break;
          case '#':
          default:
            map.setTile(x, y, Tile.createWall());
            break;
        }
      }
    }

    return { map, playerSpawn };
  }

  public toAscii(playerPos?: Point): string {
    const rows: string[] = [];
    for (let y = 0; y < this.height; y++) {
      let line = '';
      for (let x = 0; x < this.width; x++) {
        if (playerPos && playerPos.x === x && playerPos.y === y) {
          line += '@';
          continue;
        }
        const tile = this.getTile(x, y)!;
        if (tile.type === TileType.WALL) {
          line += '#';
        } else if (tile.type === TileType.FLOOR) {
          line += '.';
        } else if (tile.type === TileType.WATER) {
          line += '~';
        } else if (tile.type === TileType.DOOR) {
          line += tile.doorState === DoorState.OPEN ? '/' : '+';
        } else if (tile.type === TileType.STAIRS_UP) {
          line += '<';
        } else if (tile.type === TileType.STAIRS_DOWN) {
          line += '>';
        } else if (tile.type === TileType.PORTAL) {
          line += 'O';
        }
      }
      rows.push(line);
    }
    return rows.join('\n');
  }
}
